using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class F1WildInspectNear {public static object Run(){var ts=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var r=ts.SelectMany(t=>t.GetComponents<Renderer>()).Where(r=>r.bounds.max.x<-55&&r.bounds.min.x>-120&&r.bounds.max.z>-55&&r.bounds.min.z<-15).Select(r=>new{path=AnimationUtility.CalculateTransformPath(r.transform,null),mesh=r.GetComponent<MeshFilter>()?.sharedMesh.name,position=r.transform.position.ToString(),scale=r.transform.lossyScale.ToString(),size=r.bounds.size.ToString(),materials=r.sharedMaterials.Select(m=>m.name).ToArray()}).ToArray();string output=Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_WildernessDetail/near_objects.json");File.WriteAllText(output,JsonConvert.SerializeObject(r,Formatting.Indented));return new{near=r.Length,aggregate=ts.SelectMany(t=>t.GetComponents<MeshFilter>()).Where(f=>f.name.Contains("Veget")||f.name.Contains("Overgrowth")||f.name.Contains("Grass")||f.name.Contains("Scrub")||f.name.Contains("Plant")).Where(f=>!AnimationUtility.CalculateTransformPath(f.transform,null).Contains("WildernessEnding")).Select(f=>new{path=AnimationUtility.CalculateTransformPath(f.transform,null),asset=AssetDatabase.GetAssetPath(f.sharedMesh),bounds=f.GetComponent<Renderer>().bounds.ToString()}).ToArray(),source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Afrer_Seconds/05.Model/Environment/1F/WD_GrassA.fbx").GetComponentsInChildren<MeshFilter>().Select(f=>new{f.name,position=f.transform.localPosition.ToString(),rotation=f.transform.localEulerAngles.ToString(),scale=f.transform.localScale.ToString(),bounds=f.sharedMesh.bounds.ToString()}).ToArray()};}}
